/**
 * Arithmetic in the binary extension fields that Aztec error correction is built on.
 *
 * <p>ISO/IEC 24778 assigns one field GF(2^m) to each data codeword width m {@code = 6, 8, 10, 12},
 * plus GF(16) for the four-bit words of the mode message. Each field is generated by a primitive
 * polynomial; exponentiation by the primitive element is tabulated so that products become sums of
 * logarithms.
 *
 * Port of {@code org.bars4j.encode.matrix.aztec.AztecField}.
 */
export class AztecField {
  /** {@code x^4 + x + 1}, used for the 4-bit words of the mode message. */
  private static readonly GF16 = new AztecField(0x13, 16);
  /** {@code x^6 + x + 1}, used for 6-bit data codewords. */
  private static readonly GF64 = new AztecField(0x43, 64);
  /** {@code x^8 + x^5 + x^3 + x^2 + 1}, used for 8-bit data codewords. */
  private static readonly GF256 = new AztecField(0x12d, 256);
  /** {@code x^10 + x^3 + 1}, used for 10-bit data codewords. */
  private static readonly GF1024 = new AztecField(0x409, 1024);
  /** {@code x^12 + x^6 + x^5 + x^3 + 1}, used for 12-bit data codewords. */
  private static readonly GF4096 = new AztecField(0x1069, 4096);

  private readonly elementCountValue: number;
  private readonly alphaPower: number[];
  private readonly logarithm: number[];

  /**
   * Builds the field of {@code elementCount} elements generated by {@code modulus}.
   *
   * @param modulus      primitive polynomial, bit {@code i} carrying the coefficient of {@code x^i}
   * @param elementCount number of field elements, {@code 2^m}
   */
  private constructor(modulus: number, elementCount: number) {
    this.elementCountValue = elementCount;
    this.alphaPower = new Array<number>(elementCount).fill(0);
    this.logarithm = new Array<number>(elementCount).fill(0);

    // Successive powers of the primitive element alpha = 2, reduced by the polynomial whenever
    // they reach the top bit. alphaPower[m] is never used as a storage slot for a log.
    let element = 1;
    for (let i = 0; i < elementCount; i++) {
      this.alphaPower[i] = element;
      element <<= 1;
      if (element >= elementCount) {
        element ^= modulus;
      }
    }
    // The powers repeat with period elementCount - 1; zero itself has no logarithm.
    for (let i = 0; i < elementCount - 1; i++) {
      this.logarithm[this.alphaPower[i]] = i;
    }
  }

  /** Returns the field used for codewords of the given width. */
  static forWordSize(wordSize: number): AztecField {
    switch (wordSize) {
      case 4:
        return AztecField.GF16;
      case 6:
        return AztecField.GF64;
      case 8:
        return AztecField.GF256;
      case 10:
        return AztecField.GF1024;
      case 12:
        return AztecField.GF4096;
      default:
        throw new RangeError(`No Aztec field for a ${wordSize}-bit codeword`);
    }
  }

  /** Returns {@code alpha} raised to {@code exponent}, reduced modulo the multiplicative order. */
  exp(exponent: number): number {
    let reduced = exponent % (this.elementCountValue - 1);
    if (reduced < 0) {
      reduced += this.elementCountValue - 1;
    }
    return this.alphaPower[reduced];
  }

  /** Returns the discrete logarithm of {@code value}, which must be non-zero. */
  log(value: number): number {
    if (value === 0) {
      throw new RangeError("log(0) is undefined");
    }
    return this.logarithm[value];
  }

  /** Multiplies two field elements. */
  multiply(a: number, b: number): number {
    if (a === 0 || b === 0) {
      return 0;
    }
    return this.alphaPower[(this.logarithm[a] + this.logarithm[b]) % (this.elementCountValue - 1)];
  }
}
